// TypeScript Version: 4.1

/* eslint-disable max-lines */

import BooleanTensor0D = require( '@stdlib/ndarray/tensor0d/bool' );
import Complex64Tensor0D = require( '@stdlib/ndarray/tensor0d/complex64' );
import Complex128Tensor0D = require( '@stdlib/ndarray/tensor0d/complex128' );
import tensor0d = require( '@stdlib/ndarray/tensor0d/ctor' );
import Float32Tensor0D = require( '@stdlib/ndarray/tensor0d/float32' );
import Float64Tensor0D = require( '@stdlib/ndarray/tensor0d/float64' );
import GenericTensor0D = require( '@stdlib/ndarray/tensor0d/generic' );
import Int8Tensor0D = require( '@stdlib/ndarray/tensor0d/int8' );
import Int16Tensor0D = require( '@stdlib/ndarray/tensor0d/int16' );
import Int32Tensor0D = require( '@stdlib/ndarray/tensor0d/int32' );
import Uint8Tensor0D = require( '@stdlib/ndarray/tensor0d/uint8' );
import Uint8ClampedTensor0D = require( '@stdlib/ndarray/tensor0d/uint8c' );
import Uint16Tensor0D = require( '@stdlib/ndarray/tensor0d/uint16' );
import Uint32Tensor0D = require( '@stdlib/ndarray/tensor0d/uint32' );

/**
* Interface describing the `tensor0d` namespace.
*/
interface Namespace {
	/**
	* Creates a boolean zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.BooleanTensor0D();
	* // returns <ndarray>[ false ]
	*
	* @example
	* var arr = new ns.BooleanTensor0D( true );
	* // returns <ndarray>[ true ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 9 );
	* var arr = new ns.BooleanTensor0D( buf, 8 );
	* // returns <ndarray>[ false ]
	*/
	BooleanTensor0D: typeof BooleanTensor0D;

	/**
	* Creates a single-precision complex floating-point zero-dimensional ndarray.
	*
	* ## Notes
	*
	* -   If provided a number, the function returns a zero-dimensional ndarray containing a complex number whose real component equals the provided scalar value and whose imaginary component is zero.
	*
	* @param arg0 - scalar, real component, or buffer
	* @param arg1 - byte offset or imaginary component
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Complex64Tensor0D();
	* // returns <ndarray>[ <Complex64>[ 0.0, 0.0 ] ]
	*
	* @example
	* var arr = new ns.Complex64Tensor0D( 1.0 );
	* // returns <ndarray>[ <Complex64>[ 1.0, 0.0 ] ]
	*
	* @example
	* var Complex64 = require( '@stdlib/complex/float32/ctor' );
	*
	* var arr = new ns.Complex64Tensor0D( new Complex64( 1.0, 2.0 ) );
	* // returns <ndarray>[ <Complex64>[ 1.0, 2.0 ] ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new ns.Complex64Tensor0D( buf, 16 );
	* // returns <ndarray>[ <Complex64>[ 0.0, 0.0 ] ]
	*/
	Complex64Tensor0D: typeof Complex64Tensor0D;

	/**
	* Creates a double-precision complex floating-point zero-dimensional ndarray.
	*
	* ## Notes
	*
	* -   If provided a number, the function returns a zero-dimensional ndarray containing a complex number whose real component equals the provided scalar value and whose imaginary component is zero.
	*
	* @param arg0 - scalar, real component, or buffer
	* @param arg1 - byte offset or imaginary component
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Complex128Tensor0D();
	* // returns <ndarray>[ <Complex128>[ 0.0, 0.0 ] ]
	*
	* @example
	* var arr = new ns.Complex128Tensor0D( 1.0 );
	* // returns <ndarray>[ <Complex128>[ 1.0, 0.0 ] ]
	*
	* @example
	* var Complex128 = require( '@stdlib/complex/float64/ctor' );
	*
	* var arr = new ns.Complex128Tensor0D( new Complex128( 1.0, 2.0 ) );
	* // returns <ndarray>[ <Complex128>[ 1.0, 2.0 ] ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new ns.Complex128Tensor0D( buf, 16 );
	* // returns <ndarray>[ <Complex128>[ 0.0, 0.0 ] ]
	*/
	Complex128Tensor0D: typeof Complex128Tensor0D;

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param dtype - data type (default: 'float64')
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var arr = ns.tensor0d();
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float64'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var arr = ns.tensor0d( 1.0 );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float64'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var arr = ns.tensor0d( 1.0, 'float32' );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 12 );
	* var arr = ns.tensor0d( buf, 8, 'int32' );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'int32'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = ns.tensor0d( buf, 8, 'int32', {} );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'int32'
	*
	* @example
	* var getDType = require( '@stdlib/ndarray/dtype' );
	*
	* var Float32Tensor0D = ns.tensor0d.factory( 'float32' );
	*
	* var arr = new Float32Tensor0D( 1.0 );
	* // returns <ndarray>
	*
	* var dt = String( getDType( arr ) );
	* // returns 'float32'
	*/
	tensor0d: typeof tensor0d;

	/**
	* Creates a single-precision floating-point zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Float32Tensor0D();
	* // returns <ndarray>[ 0.0 ]
	*
	* @example
	* var arr = new ns.Float32Tensor0D( 1.0 );
	* // returns <ndarray>[ 1.0 ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 12 );
	* var arr = new ns.Float32Tensor0D( buf, 8 );
	* // returns <ndarray>[ 0.0 ]
	*/
	Float32Tensor0D: typeof Float32Tensor0D;

	/**
	* Creates a double-precision floating-point zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Float64Tensor0D();
	* // returns <ndarray>[ 0.0 ]
	*
	* @example
	* var arr = new ns.Float64Tensor0D( 1.0 );
	* // returns <ndarray>[ 1.0 ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 16 );
	* var arr = new ns.Float64Tensor0D( buf, 8 );
	* // returns <ndarray>[ 0.0 ]
	*/
	Float64Tensor0D: typeof Float64Tensor0D;

	/**
	* Creates a "generic" zero-dimensional ndarray.
	*
	* @param value - scalar value
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.GenericTensor0D( 1.0 );
	* // returns <ndarray>[ 1.0 ]
	*/
	GenericTensor0D: typeof GenericTensor0D;

	/**
	* Creates an 8-bit signed integer zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Int8Tensor0D();
	* // returns <ndarray>[ 0 ]
	*
	* @example
	* var arr = new ns.Int8Tensor0D( 1 );
	* // returns <ndarray>[ 1 ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 9 );
	* var arr = new ns.Int8Tensor0D( buf, 8 );
	* // returns <ndarray>[ 0 ]
	*/
	Int8Tensor0D: typeof Int8Tensor0D;

	/**
	* Creates a 16-bit signed integer zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Int16Tensor0D();
	* // returns <ndarray>[ 0 ]
	*
	* @example
	* var arr = new ns.Int16Tensor0D( 1 );
	* // returns <ndarray>[ 1 ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 10 );
	* var arr = new ns.Int16Tensor0D( buf, 8 );
	* // returns <ndarray>[ 0 ]
	*/
	Int16Tensor0D: typeof Int16Tensor0D;

	/**
	* Creates a 32-bit signed integer zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Int32Tensor0D();
	* // returns <ndarray>[ 0 ]
	*
	* @example
	* var arr = new ns.Int32Tensor0D( 1 );
	* // returns <ndarray>[ 1 ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 12 );
	* var arr = new ns.Int32Tensor0D( buf, 8 );
	* // returns <ndarray>[ 0 ]
	*/
	Int32Tensor0D: typeof Int32Tensor0D;

	/**
	* Creates an 8-bit unsigned integer zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Uint8Tensor0D();
	* // returns <ndarray>[ 0 ]
	*
	* @example
	* var arr = new ns.Uint8Tensor0D( 1 );
	* // returns <ndarray>[ 1 ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 9 );
	* var arr = new ns.Uint8Tensor0D( buf, 8 );
	* // returns <ndarray>[ 0 ]
	*/
	Uint8Tensor0D: typeof Uint8Tensor0D;

	/**
	* Creates a clamped 8-bit unsigned integer zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Uint8ClampedTensor0D();
	* // returns <ndarray>[ 0 ]
	*
	* @example
	* var arr = new ns.Uint8ClampedTensor0D( 1 );
	* // returns <ndarray>[ 1 ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 9 );
	* var arr = new ns.Uint8ClampedTensor0D( buf, 8 );
	* // returns <ndarray>[ 0 ]
	*/
	Uint8ClampedTensor0D: typeof Uint8ClampedTensor0D;

	/**
	* Creates a 16-bit unsigned integer zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Uint16Tensor0D();
	* // returns <ndarray>[ 0 ]
	*
	* @example
	* var arr = new ns.Uint16Tensor0D( 1 );
	* // returns <ndarray>[ 1 ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 10 );
	* var arr = new ns.Uint16Tensor0D( buf, 8 );
	* // returns <ndarray>[ 0 ]
	*/
	Uint16Tensor0D: typeof Uint16Tensor0D;

	/**
	* Creates a 32-bit unsigned integer zero-dimensional ndarray.
	*
	* @param arg - scalar or buffer
	* @param byteOffset - integer byte offset specifying the location of the scalar value (default: 0)
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only ndarray
	* @param options.order - memory layout (either row-major or column-major)
	* @returns zero-dimensional ndarray
	*
	* @example
	* var arr = new ns.Uint32Tensor0D();
	* // returns <ndarray>[ 0 ]
	*
	* @example
	* var arr = new ns.Uint32Tensor0D( 1 );
	* // returns <ndarray>[ 1 ]
	*
	* @example
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 12 );
	* var arr = new ns.Uint32Tensor0D( buf, 8 );
	* // returns <ndarray>[ 0 ]
	*/
	Uint32Tensor0D: typeof Uint32Tensor0D;
}

/**
* Zero-dimensional ndarray constructors and associated utilities.
*/
declare var ns: Namespace;


// EXPORTS //

export = ns;
